INSERT INTO quest (quest_set_id, order_index, title, description, hint, solution, setup_cmd, grade_cmd, kind, choices, answer_index, explanation, answer_spec, template, checks, docs) VALUES
  (431, 1, '대상 서비스', '타이머 유닛은 기본으로 **어떤 서비스** 를 활성화할까요?', '이름이 같아요.', NULL, NULL, '[]', 'choice', '["항상 default.target 에 묶인 서비스", "가장 최근에 시작한 서비스", "같은 이름의 서비스", "반드시 Unit= 로 지정한 서비스"]', 2, 'systemd.timer 문서는 기본으로 접미사를 뺀 같은 이름의 서비스가 활성화되며 활성화 대상은 Unit= 으로 바꿀 수 있다고 설명합니다.', NULL, NULL, NULL, '[{"title": "systemd.timer(5) man page", "url": "https://man7.org/linux/man-pages/man5/systemd.timer.5.html"}]'),
  (431, 2, 'OnCalendar', '`OnCalendar=` 는 어떤 타이머일까요?', '벽시계 기준이에요.', NULL, NULL, '[]', 'choice', '["부팅 후 경과 시간으로 정하는 타이머", "벽시계(실시간) 시각을 달력 이벤트 표현식으로 정하는 타이머", "유닛이 마지막 활성화된 뒤 경과 시간으로 정하는 타이머", "서비스 관리자가 시작한 뒤 경과 시간으로 정하는 타이머"]', 1, '문서는 OnCalendar 가 벽시계 시간(realtime)에 달력 이벤트 표현식으로 타이머를 정의한다고 설명합니다.', NULL, NULL, NULL, '[{"title": "systemd.timer(5) man page", "url": "https://man7.org/linux/man-pages/man5/systemd.timer.5.html"}]'),
  (431, 3, 'OnBootSec', '`OnBootSec=` 의 **기준점** 은 무엇일까요?', '부팅이에요.', NULL, NULL, '[]', 'choice', '["부팅 시점", "타이머 유닛 활성화 시점", "서비스 관리자 최초 시작 시점", "대상 유닛의 마지막 활성화 시점"]', 0, '문서는 OnActiveSec 가 타이머 유닛 활성화, OnBootSec 가 부팅, OnStartupSec 가 서비스 관리자 최초 시작, OnUnitActiveSec·OnUnitInactiveSec 가 대상 유닛의 마지막 활성화·비활성화 시점을 기준으로 한다고 설명합니다.', NULL, NULL, NULL, '[{"title": "systemd.timer(5) man page", "url": "https://man7.org/linux/man-pages/man5/systemd.timer.5.html"}]'),
  (431, 4, 'OnUnitActiveSec', '`OnUnitActiveSec=` 의 **기준점** 은 무엇일까요?', '대상 유닛이 기준이에요.', NULL, NULL, '[]', 'choice', '["부팅한 시점", "타이머 유닛이 활성화된 때", "마지막으로 비활성화된 때", "유닛이 마지막 활성화된 때"]', 3, '문서는 OnUnitActiveSec 가 대상 유닛의 마지막 활성화 시점, OnUnitInactiveSec 가 마지막 비활성화 시점을 기준으로 한다고 설명합니다.', NULL, NULL, NULL, '[{"title": "systemd.timer(5) man page", "url": "https://man7.org/linux/man-pages/man5/systemd.timer.5.html"}]'),
  (431, 5, 'Persistent', '`Persistent=true` 의 효과로 맞는 것은 무엇일까요?', '놓친 실행이에요.', NULL, NULL, '[]', 'choice', '["모든 모노토닉 타이머에서 놓친 실행을 보정한다", "타이머가 재시작되어도 상태를 지운다", "놓친 실행을 활성화 시 즉시 실행", "실행 시각의 지연을 완전히 없앤다"]', 2, '문서는 Persistent 가 타이머가 비활성이던 동안 최소 한 번 실행되었어야 하면 활성화 시 즉시 실행하며 OnCalendar 에만 효과가 있고 기본값은 false 라고 설명합니다.', NULL, NULL, NULL, '[{"title": "systemd.timer(5) man page", "url": "https://man7.org/linux/man-pages/man5/systemd.timer.5.html"}]'),
  (431, 6, 'AccuracySec', '`AccuracySec=` 의 **기본값** 은 얼마일까요?', '1 분이에요.', NULL, NULL, '[]', 'choice', '["10s", "1min", "1h", "5min"]', 1, '문서는 AccuracySec 의 기본값이 1min 이라고 설명합니다.', NULL, NULL, NULL, '[{"title": "systemd.timer(5) man page", "url": "https://man7.org/linux/man-pages/man5/systemd.timer.5.html"}]'),
  (431, 7, 'RandomizedDelaySec', '`RandomizedDelaySec=` 는 무엇을 할까요?', '무작위 지연이에요.', NULL, NULL, '[]', 'choice', '["무작위 지연을 균등 분포로 더한다", "항상 지정값만큼 고정으로 지연한다", "실행 횟수를 무작위로 줄인다", "서비스를 무작위로 재시작한다"]', 0, '문서는 RandomizedDelaySec 가 0 부터 지정값 사이에서 균등 분포로 무작위 지연을 더하며 기본값이 0 이라고 설명합니다.', NULL, NULL, NULL, '[{"title": "systemd.timer(5) man page", "url": "https://man7.org/linux/man-pages/man5/systemd.timer.5.html"}]'),
  (431, 8, 'WakeSystem', '`WakeSystem=` 의 **기본값** 은 무엇일까요?', '서스펜드를 깨우는 옵션이에요.', NULL, NULL, '[]', 'choice', '["true", "시스템이 지원하면 true", "OnCalendar 일 때만 true", "false"]', 3, '문서는 WakeSystem 이 true 이면 지원하는 시스템에서 서스펜드를 깨워 타이머를 실행하며 기본값이 false 라고 설명합니다.', NULL, NULL, NULL, '[{"title": "systemd.timer(5) man page", "url": "https://man7.org/linux/man-pages/man5/systemd.timer.5.html"}]'),
  (431, 9, 'RemainAfterElapse', '`RemainAfterElapse=` 의 **기본값** 과 의미는 무엇일까요?', '경과 후에도 남아요.', NULL, NULL, '[]', 'choice', '["기본 false 이며 경과 후 즉시 언로드된다", "기본 true 이며 경과 후 항상 재시작된다", "기본 true 이며 경과 후에도 타이머가 로드된 상태로 남는다", "기본 false 이며 Persistent 와 같은 의미다"]', 2, '문서는 RemainAfterElapse 의 기본값이 true 이며 true 이면 타이머가 경과 후에도 로드된 상태로 남는다고 설명합니다.', NULL, NULL, NULL, '[{"title": "systemd.timer(5) man page", "url": "https://man7.org/linux/man-pages/man5/systemd.timer.5.html"}]'),
  (431, 10, '달력 타이머', '벽시계 **달력 표현식** 으로 실행 시각을 정하는 키입니다. 빈칸을 채우세요.', '"달력에서" 라는 뜻이에요.', NULL, NULL, '[]', 'fill', '["OnCalendar", "OnBootSec", "OnActiveSec", "OnUnitActiveSec"]', NULL, 'OnCalendar 는 벽시계 시간에 달력 이벤트 표현식으로 정의합니다. 나머지는 모노토닉 타이머입니다.', '[0]', '[Timer]
